//! Batch connection readiness on the existing application runtime. UDP ingress
//! remains separately driven. Each child retains its own wake registration;
//! FuturesUnordered preserves ready-queue cooperation and wake-during-poll.
use std::{
    future::Future,
    io,
    panic::{AssertUnwindSafe, catch_unwind},
    pin::Pin,
    sync::{
        Arc,
        atomic::{AtomicUsize, Ordering},
    },
    task::{Context, Poll},
    time::Instant,
};

use futures_util::{StreamExt, stream::FuturesUnordered};
use tokio::{sync::mpsc, task::JoinHandle};
use wtransport::quinn::{AsyncTimer, AsyncUdpSocket, Runtime, TokioRuntime};

type Driver = Pin<Box<dyn Future<Output = ()> + Send>>;

/// Keep both polling and destruction inside the child failure boundary.
struct IsolatedDriver {
    future: Option<Driver>,
}

impl IsolatedDriver {
    fn discard(&mut self) {
        let future = self.future.take();
        if catch_unwind(AssertUnwindSafe(|| drop(future))).is_err() {
            tracing::error!("QUIC connection driver destruction panicked");
        }
    }
}

impl Future for IsolatedDriver {
    type Output = ();

    fn poll(self: Pin<&mut Self>, cx: &mut Context<'_>) -> Poll<()> {
        let this = self.get_mut();
        match catch_unwind(AssertUnwindSafe(|| {
            this.future.as_mut().expect("live driver").as_mut().poll(cx)
        })) {
            Ok(Poll::Pending) => Poll::Pending,
            result => {
                if result.is_err() {
                    tracing::error!("QUIC connection driver polling panicked");
                }
                this.discard();
                Poll::Ready(())
            }
        }
    }
}

impl Drop for IsolatedDriver {
    fn drop(&mut self) {
        self.discard();
    }
}

/// Outer service ownership, separate from runtime handles retained by drivers.
/// Dropping it cancels parked drivers as well as workers waiting for admission.
pub(super) struct DriverPool {
    workers: Vec<JoinHandle<()>>,
}

#[derive(Debug)]
pub(super) struct DriverRuntime {
    incoming: Vec<mpsc::UnboundedSender<Driver>>,
    next: AtomicUsize,
}

impl DriverPool {
    pub(super) fn new() -> (Arc<DriverRuntime>, Self) {
        // Match actual runtime parallelism, including current-thread test runtimes.
        let count = tokio::runtime::Handle::current().metrics().num_workers();
        let mut incoming = Vec::with_capacity(count);
        let mut workers = Vec::with_capacity(count);
        for _ in 0..count {
            let (send, mut receive) = mpsc::unbounded_channel::<Driver>();
            incoming.push(send);
            workers.push(tokio::spawn(async move {
                let mut active = FuturesUnordered::new();
                loop {
                    tokio::select! {
                        driver = receive.recv() => match driver {
                            Some(driver) => active.push(IsolatedDriver { future: Some(driver) }),
                            None => break,
                        },
                        _ = active.next(), if !active.is_empty() => {},
                    }
                }
            }));
        }
        (
            Arc::new(DriverRuntime {
                incoming,
                next: AtomicUsize::new(0),
            }),
            Self { workers },
        )
    }
}

impl Drop for DriverPool {
    fn drop(&mut self) {
        for worker in &self.workers {
            worker.abort();
        }
    }
}

impl Runtime for DriverRuntime {
    fn new_timer(&self, deadline: Instant) -> Pin<Box<dyn AsyncTimer>> {
        TokioRuntime.new_timer(deadline)
    }

    fn spawn(&self, future: Driver) {
        // Endpoint creation happens inside the independent ingress runtime.
        TokioRuntime.spawn(future);
    }

    fn spawn_connection(&self, future: Driver) {
        let index = self.next.fetch_add(1, Ordering::Relaxed) % self.incoming.len();
        if let Err(error) = self.incoming[index].send(future) {
            // An unexpectedly retired worker must not silently discard a driver.
            tracing::warn!("QUIC driver worker unavailable; using independent task");
            TokioRuntime.spawn(error.0);
        }
    }

    fn wrap_udp_socket(&self, socket: std::net::UdpSocket) -> io::Result<Arc<dyn AsyncUdpSocket>> {
        TokioRuntime.wrap_udp_socket(socket)
    }

    fn now(&self) -> Instant {
        TokioRuntime.now()
    }
}

#[cfg(test)]
mod tests {
    use super::*;
    use tokio::{
        sync::oneshot,
        time::{Duration, timeout},
    };

    #[tokio::test]
    async fn child_wakes_stay_independent_and_panics_do_not_retire_the_worker() {
        let (runtime, _pool) = DriverPool::new();
        let (first_send, first_receive) = oneshot::channel();
        let (second_send, second_receive) = oneshot::channel();
        let (first_done, first_result) = oneshot::channel();
        let (second_done, mut second_result) = oneshot::channel();
        runtime.spawn_connection(Box::pin(async move {
            first_receive.await.unwrap();
            let _ = first_done.send(());
        }));
        let (panic_lifetime, panic_observed) = oneshot::channel::<()>();
        runtime.spawn_connection(Box::pin(async move {
            let _lifetime = panic_lifetime;
            panic!("isolated child driver failure");
        }));
        runtime.spawn_connection(Box::pin(async move {
            second_receive.await.unwrap();
            let _ = second_done.send(());
        }));
        first_send.send(()).unwrap();
        timeout(Duration::from_secs(5), first_result)
            .await
            .unwrap()
            .unwrap();
        assert!(
            timeout(Duration::from_secs(5), panic_observed)
                .await
                .unwrap()
                .is_err()
        );
        assert!(matches!(
            second_result.try_recv(),
            Err(oneshot::error::TryRecvError::Empty)
        ));
        second_send.send(()).unwrap();
        timeout(Duration::from_secs(5), second_result)
            .await
            .unwrap()
            .unwrap();
    }

    #[tokio::test]
    async fn child_destruction_panic_does_not_cancel_parked_siblings() {
        struct BadDrop(Option<oneshot::Sender<()>>);
        impl Future for BadDrop {
            type Output = ();
            fn poll(self: Pin<&mut Self>, _: &mut Context<'_>) -> Poll<()> {
                Poll::Ready(())
            }
        }
        impl Drop for BadDrop {
            fn drop(&mut self) {
                let _ = self.0.take().unwrap().send(());
                panic!("isolated driver destruction failure");
            }
        }
        let (runtime, _pool) = DriverPool::new();
        let (wake, parked) = oneshot::channel();
        let (done, completed) = oneshot::channel();
        runtime.spawn_connection(Box::pin(async move {
            parked.await.unwrap();
            let _ = done.send(());
        }));
        let (dropped, observed) = oneshot::channel();
        runtime.spawn_connection(Box::pin(BadDrop(Some(dropped))));
        timeout(Duration::from_secs(5), observed)
            .await
            .unwrap()
            .unwrap();
        wake.send(()).unwrap();
        timeout(Duration::from_secs(5), completed)
            .await
            .unwrap()
            .unwrap();
    }

    #[tokio::test]
    async fn dropping_pool_cancels_parked_driver_ownership() {
        let (runtime, pool) = DriverPool::new();
        let (started, start) = oneshot::channel();
        let (lifetime, ended) = oneshot::channel::<()>();
        runtime.spawn_connection(Box::pin(async move {
            let _lifetime = lifetime;
            let _ = started.send(());
            std::future::pending::<()>().await;
        }));
        timeout(Duration::from_secs(5), start)
            .await
            .unwrap()
            .unwrap();
        drop(pool);
        assert!(
            timeout(Duration::from_secs(5), ended)
                .await
                .unwrap()
                .is_err()
        );
    }
}

